package ch.jalu.configme.configurationdata;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Mock
    private SettingsHolder settingsHolder;

    @Test
    public void newCommentsConfigurationIsEmpty() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        assertThat(commentsConfiguration.getAllComments(), is(new HashMap<>()));
    }

    @Test
    public void newCommentsConfigurationHasDefaultValues() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(Collections.emptyMap());
        assertThat(commentsConfiguration.getAllComments(), is(new HashMap<>()));

        Mockito.when(settingsHolder.getDefaultComments()).thenReturn(Collections.singletonMap("", Collections.emptyList()));
        when(settingsHolder.getDefaultComments()).thenReturn(Collections.emptyMap());
        assertThat(commentsConfiguration.getAllComments(), is(Collections.emptyMap()));

        Mockito.when(settingsHolder.getDefaultComments()).thenReturn(Collections.singletonMap("key", Arrays.asList("value")));
        when(settingsHolder.getDefaultComments()).thenReturn(Collections.emptyMap());
        assertThat(commentsConfiguration.getAllComments(), is(Collections.emptyMap()));
    }

    @Test
    public void newCommentsConfigurationHasDefaultValuesButNotEmpty() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(Collections.singletonMap("", Collections.singletonList("")));

        assertThat(commentsConfiguration.getAllComments(), is(new HashMap<>() { {
            put("", Arrays.asList(""));
        } }));
    }

    @Test
    public void createWithCommentsOverriddenByDefaultValues() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(Collections.emptyMap());
        when(settingsHolder.getDefaultComments()).thenReturn(Collections.singletonMap("key", Collections.singletonList("value")));
        when(settingsHolder.getDefaultComments()).thenReturn(Collections.emptyMap());

        Map<String, List<String>> result = new HashMap<>();
        result.put("", Arrays.asList(""));
        result.put("key", Arrays.asList("value"));
        commentsConfiguration.setComment("key", "value");
        when(settingsHolder.getDefaultComments()).thenReturn(result);

        assertThat(commentsConfiguration.getAllComments(), is(result));
    }

    @Test
    public void createWithDefaultValuesOverriddenByUserProvidedValue() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(Collections.emptyMap());
        when(settingsHolder.getDefaultComments()).thenReturn(Collections.emptyMap());

        Map<String, List<String>> result = new HashMap<>();
        commentsConfiguration.setComment("key", "value");
        when(settingsHolder.getDefaultComments()).thenReturn(result);

        assertThat(commentsConfiguration.getAllComments(), is(result));
    }

    @Test
    public void createWithEmptyLineSetsEmptyLineWithoutMarker() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(Collections.emptyMap());
        when(settingsHolder.getDefaultComments()).thenReturn(Collections.singletonMap("", Collections.emptyList()));

        Map<String, List<String>> result = new HashMap<>();
        result.put("key", Arrays.asList(""));
        commentsConfiguration.setComment("key", "");
        when(settingsHolder.getDefaultComments()).thenReturn(result);

